mapper.select:
select event_id eventId, event_type eventType, payload_version payloadVersion, aggregate_type aggregateType,
       aggregate_id aggregateId, aggregate_no aggregateNo, idempotency_key idempotencyKey,
       payload, event_status eventStatus, retry_count retryCount, next_retry_time nextRetryTime,
       processed_time processedTime, error_message errorMessage, create_by createBy, create_time createTime
from business_event

    and event_status=#{eventStatus}
    and event_type=#{eventType}
    and aggregate_type=#{aggregateType}
    and aggregate_id=#{aggregateId}

order by event_id desc
